170	    (volatile uint32_t *)DCACHE_CACHE_CTRL;
171	  volatile uint32_t *dcache_status =
172	    (volatile uint32_t *)DCACHE_CACHE_STATUS;
173	  volatile uint32_t *dcache_stb =
174	    (volatile uint32_t *)DCACHE_STB_TIMEOUT_CTRL;
175	  volatile uint32_t timeout = RV1126B_DIAG_POLL_TIMEOUT;
176	
177	  /* Set the uncache region to cover peripheral address space */
178	
179	  *grf_cache_start = 0x20000;
180	  *grf_cache_end   = 0x23000;
181	
182	  /* Enable DCache: cache_en=1, stb_entry=7, stb_timeout_en=1 */
183	
184	  *dcache_ctrl |= DCACHE_CACHE_EN_BIT |
185	                  DCACHE_CACHE_ENTRY_THRESH |
186	                  DCACHE_STB_TIMEOUT_EN_BIT;
187	
188	  /* Enable store buffer timeout */
189	
190	  *dcache_stb = 1;
191	
192	  /* Wait for cache initialization to finish */
193	
194	  while ((*dcache_status & DCACHE_INIT_FINISH_BIT) == 0)
195	    {
196	      if (timeout-- == 0)
197	        {
198	          riscv_lowputc('X');
199	          return false;
200	        }
201	    }
202	
203	  /* Clear bypass to enable caching */
204	
205	  *dcache_ctrl &= ~DCACHE_CACHE_BYPASS_BIT;
206	  return true;
207	}
