172	 * Name: rv1126b_get_active_irq
173	 *
174	 * Description:
175	 *   Scan the INTMUX status registers to find the highest-priority
176	 *   active (pending and enabled) IRQ.
177	 *
178	 * Returned Value:
179	 *   IRQ number (0..255), or -1 if no active IRQ is found.
180	 *
181	 ****************************************************************************/
182	
183	static int rv1126b_get_active_irq(void)
184	{
185	  int i;
186	  unsigned int status;
187	
188	  for (i = 0; i < INTMUX_NGROUPS; i++)
189	    {
190	      status = getreg32(RV1126B_INTMUX_BASE +
191	                         RV1126B_INTMUX_STATUS_OFFSET +
192	                         (i * RV1126B_INTMUX_GROUP_STRIDE));
193	      if (status != 0)
194	        {
195	          /* Find the lowest-numbered (highest priority) set bit */
196	
197	          int bit = __builtin_ctz(status);
198	          return i * INTMUX_IRQS_PER_GROUP + bit;
199	        }
