209	/****************************************************************************
210	 * Name: riscv_dispatch_irq
211	 *
212	 * Description:
213	 *   Dispatch an interrupt based on the mcause value.
214	 *
215	 *   This function is called from the NuttX RISC-V common interrupt
216	 *   handling path (riscv_doirq -> riscv_dispatch_irq) when the mcause
217	 *   indicates an interrupt (bit 31 set).
218	 *
219	 *   For the RV1126B HPMCU:
220	 *     - mcause == 7  (IRQ_M_TIMER): machine timer interrupt
221	 *     - mcause == 11 (IRQ_M_EXT):   machine external interrupt
222	 *       (routed through INTMUX)
223	 *
224	 * Input Parameters:
225	 *   mcause - The value of the mcause CSR
226	 *   regs   - Pointer to the saved register context
227	 *
228	 * Returned Value:
229	 *   Pointer to the (possibly new) register context after dispatch.
230	 *
231	 ****************************************************************************/
232	
233	void *riscv_dispatch_irq(uintptr_t mcause, uintreg_t *regs)
234	{
235	  uintptr_t cause;
236	
237	  if ((mcause & MCAUSE_INTERRUPT_BIT) == 0)
238	    {
239	      /* Synchronous exception (ecall, illegal instruction, etc.).
240	       * Must go through riscv_doirq() so NuttX can advance mepc
241	       * for ecall and handle context switching properly.
242	       *
243	       * Exception 6 (Store/AMO address misaligned) gets a one-shot
244	       * frame dump and then halts; every other cause (notably 11 /
245	       * M-mode ecall) keeps the original eXX + riscv_doirq path.
246	       */
247	
248	      if ((mcause & 0xff) == RV1126B_MCAUSE_STORE_MIS)
249	        {
250	          /* One-shot lock: only the first misaligned-store trap dumps. */
251	
252	          if (g_rv1126b_misalign_lock == 0)
253	            {
254	              g_rv1126b_misalign_lock = 1;
255	
256	              /* Capture the whole frame before any output. */
257	
258	              uint32_t cause   = (uint32_t)mcause;
259	              uint32_t mepc    = (uint32_t)regs[REG_EPC_NDX];
260	              uint32_t mtval   = (uint32_t)read_csr(0x343);
261	              uint32_t sp      = (uint32_t)regs[REG_X2_NDX];
262	              uint32_t ra      = (uint32_t)regs[REG_X1_NDX];
263	
264	              riscv_lowputc('[');
265	              riscv_lowputc('X');
266	              rv1126b_put_hex8(cause);
267	              riscv_lowputc('P');
268	              rv1126b_put_hex8(mepc);
269	              riscv_lowputc('V');
270	              rv1126b_put_hex8(mtval);
271	              riscv_lowputc('S');
272	              rv1126b_put_hex8(sp);
273	              riscv_lowputc('R');
274	              rv1126b_put_hex8(ra);
275	              riscv_lowputc(']');
276	              riscv_lowputc('\r');
277	              riscv_lowputc('\n');
278	            }
279	
280	          /* Do not return to the faulting instruction. */
281	
282	          for (;;)
283	            {
284	              __asm__ volatile("nop");
285	            }
286	        }
287	
288	      riscv_lowputc('e');
289	      {
290	        uintptr_t xc = mcause & 0xff;
291	        static const char hex[] = "0123456789abcdef";
292	        riscv_lowputc(hex[(xc >> 4) & 0xf]);
293	        riscv_lowputc(hex[xc & 0xf]);
294	      }
295	      regs = riscv_doirq((int)mcause, regs);
296	      return regs;
297	    }
298	
299	  /* Interrupt: strip the interrupt bit to get the cause code */
300	
301	  cause = mcause & ~MCAUSE_INTERRUPT_BIT;
302	
303	  if (cause == IRQ_M_TIMER)
304	    {
305	      /* Machine timer interrupt -- call the NuttX timer handler */
306	
307	      up_timer_int();
308	    }
309	  else if (cause == IRQ_M_EXT)
310	    {
311	      /* Machine external interrupt -- scan INTMUX for active IRQs */
312	
313	      int irq;
314	
315	      if (!g_path_ext_marked)
316	        {
317	          g_path_ext_marked = true;
318	          riscv_lowputc('@');
319	          riscv_lowputc('E');
320	          riscv_lowputc('@');
321	        }
322	
323	      /* Signal IPIC Start of Interrupt */
324	
325	      rv1126b_ipic_soi();
326	
327	      /* Scan for active IRQs -- handle all pending IRQs in this group */
328	
329	      while ((irq = rv1126b_get_active_irq()) >= 0)
330	        {
331	          if (irq == 61 && !g_path_uart_dispatch_marked)
332	            {
333	              g_path_uart_dispatch_marked = true;
334	              riscv_lowputc('@');
335	              riscv_lowputc('U');
336	              riscv_lowputc('@');
337	            }
338	
339	          /* Dispatch through the NuttX IRQ dispatch table.
340	           * riscv_doirq() handles context switch bookkeeping and
341	           * returns the (possibly updated) regs pointer.
342	           */
343	
344	          regs = riscv_doirq(irq, regs);
345	        }
346	
347	      /* Signal IPIC End of Interrupt */
348	
349	      rv1126b_ipic_eoi();
350	    }
351	  else
352	    {
353	      /* Unexpected interrupt cause -- spin */
354	
355	      riscv_lowputc('?');
356	      for (; ; );
357	    }
358	
359	  return regs;
360	}
