19	bool __atomic_compare_exchange_4(volatile void *ptr, void *expected,
20	                                 uint32_t desired, bool weak,
21	                                 int success_memorder, int failure_memorder)
22	{
23	  uint32_t *ep = (uint32_t *)expected;
24	  volatile uint32_t *pp = (volatile uint32_t *)ptr;
25	  uint32_t old = *ep;
26	
27	  (void)weak;
28	  (void)success_memorder;
29	  (void)failure_memorder;
30	
31	  if (*pp == old)
32	    {
33	      *pp = desired;
34	      return true;
35	    }
36	
37	  *ep = *pp;
38	  return false;
39	}
